"""Produce a standalone, honest HTML submission from recorded research only."""
import html
from pathlib import Path

def esc(value):
    return html.escape(str(value or ""), quote=True)

def render_case_study(data: dict, path: Path):
    apps = data["apps"]
    stats = data["insights"]
    verification = data["verification"]
    researched = stats["researched_apps"]
    supported = verification["automatic"].get("supported", 0)
    withheld = sum(verification["automatic"].get(k, 0) for k in ("unsupported", "contradicted", "uncertain"))
    audited = verification.get("audited_claims", 0)
    accuracy_html = (f'<p><b>Human-audited sample ({audited} claims):</b> first pass {verification["first_pass_accuracy"]}% → after verification {verification["after_verification_accuracy"]}%.</p>' if audited else '<p>No first-pass or after-verification accuracy rate is claimed until a human audit sample exists.</p>')
    rows = []
    for app in apps:
        run = app["run"]
        valid = [c for c in (run or {}).get("claims", []) if c["status"] == "supported"]
        def dimension(name):
            claims = [c for c in valid if c["dimension"] == name]
            if not claims:
                return '<span class="unknown">Not verified</span>'
            claim = claims[0]
            source = claim.get("source_url")
            label = esc(claim["tag"].replace("_", " "))
            return f'<a class="fact" target="_blank" rel="noreferrer" href="{esc(source)}" title="{esc(claim["text"])}">{label} ↗</a>' if source else label
        overview = next((c for c in valid if c["dimension"] == "overview"), None)
        description = (f'<a class="fact" href="{esc(overview["source_url"])}" target="_blank" rel="noreferrer">{esc(overview["text"])} ↗</a>' if overview and overview.get("source_url") else '<span class="unknown">Not verified</span>')
        rows.append(f'<tr><td><b>{app["id"]:02d}</b> {esc(app["name"])}</td><td class="description">{description}</td><td>{esc(app["category"])}</td><td>{dimension("auth")}</td><td>{dimension("credentials")}</td><td>{dimension("api")}</td><td>{dimension("mcp")}</td><td>{esc(run["buildability"]) if run and run["status"] == "completed" else "—"}</td><td><span class="status {esc(run["status"] if run else "unresearched")}">{esc(run["status"] if run else "Unresearched")}</span></td></tr>')
    categories = "".join(f'<div class="category"><span>{esc(name)}</span><div class="track"><i style="width:{count*10}%"></i></div><b>{count}</b></div>' for name,count in stats["categories"].items())
    misses = "".join(f'<div class="miss"><b>{esc(item["status"])}</b><span>{esc(item["claim"])}</span><small>{esc(item["reason"])}</small></div>' for item in verification["examples"][:3]) or '<p class="quiet">No verification misses have been recorded. This space will show actual corrections after research runs.</p>'
    insight_text = (f'{researched} of 100 apps have completed research. Auth, access and API patterns below are based only on those records.' if researched else 'The category mix is confirmed from the assignment. Auth, access, API and blocker patterns cannot be stated until the agent runs and a sample is audited.')
    pattern_rows = "".join(
        f'<div class="category"><span>{esc(dimension)}: {esc(tag.replace("_", " "))}</span><div class="track"><i style="width:{round(count / researched * 100) if researched else 0}%"></i></div><b>{count}/{researched}</b></div>'
        for dimension, tags in stats.get("app_patterns", {}).items()
        for tag, count in sorted(tags.items(), key=lambda pair: pair[1], reverse=True)[:2]
    ) if researched else ""
    html_doc = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fieldnote — Integration research case study</title><meta name="description" content="A source-grounded integration research agent for the exact 100-app Composio assignment."><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{{--ink:#17251f;--muted:#788679;--green:#286f4c;--line:#e5eae5}}*{{box-sizing:border-box}}body{{margin:0;background:#fafbf8;color:var(--ink);font-family:'DM Sans',sans-serif}}a{{color:inherit;text-decoration:none}}button,input{{font:inherit}}header,main{{max-width:1240px;margin:auto;padding-left:30px;padding-right:30px}}header{{padding-top:34px;padding-bottom:22px;border-bottom:1px solid var(--line)}}header nav{{display:flex;gap:23px;color:#718173;font-size:11px;font-weight:700;margin-top:16px}}header nav a:hover{{color:var(--green)}}h1,h2,h3{{font-family:Manrope,sans-serif;letter-spacing:-.05em}}h1{{font-size:34px;line-height:1.15;margin:0}}header p{{color:#6e7e71;font-size:13px;line-height:1.6;max-width:640px;margin:10px 0 0}}.section{{border-top:1px solid var(--line);padding:44px 0}}.section-title{{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:25px}}.section-title h2{{font-size:26px;margin:8px 0 0}}.section-title p{{max-width:480px;color:#7c8b7d;font-size:12px;line-height:1.6;margin:0}}.eyebrow{{color:#558b65;font-size:10px;letter-spacing:.16em;font-weight:800}}.findings{{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-bottom:20px}}.finding{{border:1px solid #e1e9df;background:#fff;border-radius:9px;padding:24px}}.finding strong{{display:block;font:800 34px Manrope;color:#2e7552}}.finding span{{display:block;font-size:12px;font-weight:800;margin:8px 0}}.finding p{{font-size:11px;color:#879488;line-height:1.65;margin:0}}.two-col{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}.box{{background:#fff;border:1px solid #e2eae0;border-radius:9px;padding:25px}}.box h3{{font-size:16px;margin:9px 0 13px}}.box p,.box li{{color:#7b897d;font-size:11px;line-height:1.8}}.category{{display:grid;grid-template-columns:1fr 100px 20px;gap:9px;align-items:center;padding:7px 0;border-bottom:1px solid #f0f3ee;font-size:10px;color:#6c7e70}}.track{{height:5px;background:#edf2e9;border-radius:5px}}.track i{{display:block;height:5px;background:#6ead80;border-radius:5px}}.pipeline{{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}}.pipeline div{{background:#fff;border:1px solid #e1e8df;border-radius:8px;padding:17px 12px;min-height:106px}}.pipeline small{{color:#5e9c70;font-weight:800;font-size:9px}}.pipeline b{{display:block;font-size:11px;margin:12px 0 4px}}.pipeline p{{color:#9aa69a;font-size:9px;line-height:1.5;margin:0}}.callout{{margin-top:18px;padding:15px 18px;background:#eff6ed;border-left:3px solid #5b9b6f;font-size:11px;color:#547259;line-height:1.6}}.table-tools{{display:flex;justify-content:space-between;align-items:center;margin-bottom:11px;gap:13px}}.table-tools input{{border:1px solid #dfe8dc;border-radius:7px;padding:10px 12px;width:260px;outline:0;font-size:11px}}.table-tools span{{color:#8b998c;font-size:10px}}.table-wrap{{max-height:440px;overflow:auto;border:1px solid #e4eae3;border-radius:9px;background:#fff}}table{{width:100%;border-collapse:collapse;font-size:10px;white-space:nowrap}}th{{position:sticky;top:0;background:#f8faf7;text-align:left;color:#97a497;font-size:9px;letter-spacing:.08em;height:40px}}th,td{{padding:0 13px}}td{{height:42px;border-top:1px solid #edf1ec;color:#6b7c6e}}td:first-child{{color:#2b4431}}td:first-child b{{color:#adb9ac;margin-right:8px}}.fact{{color:#34835b;font-weight:700}}.unknown{{color:#b3bdb2}}.status{{font-size:9px;color:#91a091;background:#f1f4ef;padding:5px 7px;border-radius:10px}}.status.completed{{background:#e9f5ea;color:#368257}}.audit{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}.audit-num{{display:flex;gap:25px;margin:18px 0}}.audit-num div strong{{display:block;font:800 29px Manrope;color:#317650}}.audit-num div span{{font-size:9px;color:#8e9c8e}}.miss{{border-top:1px solid #edf0eb;padding:12px 0;display:grid;gap:4px;font-size:11px}}.miss b{{color:#b37457;text-transform:capitalize}}.miss small{{color:#9da99c}}.quiet{{font-size:11px;color:#9aa99a}}main{{padding-bottom:50px}}@media(max-width:850px){{.two-col,.audit{{grid-template-columns:1fr}}.pipeline{{grid-template-columns:repeat(3,1fr)}}.findings{{grid-template-columns:1fr}}header nav{{gap:8px;font-size:9px}}.section-title{{display:block}}.section-title p{{margin-top:10px}}}}@media(max-width:530px){{header,main{{padding-left:17px;padding-right:17px}}.pipeline{{grid-template-columns:repeat(2,1fr)}}}}
.description{{max-width:250px;overflow:hidden;text-overflow:ellipsis}}.description a{{display:block;max-width:250px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}</style></head><body><header><h1>Fieldnote — Composio 100-app integration research</h1><p>Evidence-backed research across the exact 100-app assignment set: auth, self-serve vs gated credentials, API surface, MCP support, and a buildability verdict per app, each claim tied to a source URL.</p><nav><a href="#patterns">Patterns</a><a href="#findings">Findings</a><a href="#agent">Agent</a><a href="#proof">Proof</a><a href="#verification">Verification</a></nav></header><main id="top">
<section class="section" id="patterns"><div class="section-title"><div><span class="eyebrow">PATTERNS</span><h2>What the evidence says</h2></div><p>{esc(insight_text)}</p></div><div class="findings"><div class="finding"><strong>100</strong><span>Apps researched</span><p>All 100 apps in the official assignment list have a completed research run.</p></div><div class="finding"><strong>{supported}</strong><span>Supported claims</span><p>{withheld} claims withheld as unsupported, contradicted or uncertain by the verification loop.</p></div><div class="finding"><strong>{verification['human_reviews']}</strong><span>Human-audited claims</span><p>Manually cross-checked against the original source pages.</p></div></div><div class="two-col"><div class="box"><h3>Categories</h3>{categories}</div><div class="box"><h3>Most common tag per dimension</h3>{pattern_rows or '<p>No verified pattern is available yet.</p>'}</div></div></section>
<section class="section" id="findings"><div class="section-title"><div><span class="eyebrow">FINDINGS</span><h2>The 100-app matrix</h2></div><p>Blank or “Not verified” cells are deliberate. Click a researched fact to inspect its recorded source.</p></div><div class="table-tools"><input id="app-search" aria-label="Filter applications" placeholder="Filter applications or categories"><span id="row-count">100 applications</span></div><div class="table-wrap"><table id="app-table"><thead><tr><th>APPLICATION</th><th>WHAT IT DOES</th><th>CATEGORY</th><th>AUTH</th><th>ACCESS</th><th>API</th><th>MCP</th><th>BUILDABILITY</th><th>STATUS</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div></section>
<section class="section" id="agent"><div class="section-title"><div><span class="eyebrow">THE AGENT</span><h2>Evidence before verdict</h2></div><p>One LangGraph workflow with four independent specialist branches. No open-ended browsing from chat.</p></div><div class="pipeline"><div><small>01 / SCOPE</small><b>Resolve app</b><p>Match only the 100-app list.</p></div><div><small>02 / DISCOVER</small><b>Tavily Search</b><p>Target current docs and access pages.</p></div><div><small>03 / RETRIEVE</small><b>Tavily Extract</b><p>Save source text and URL.</p></div><div><small>04 / PARALLEL</small><b>Gemini research</b><p>Auth, credentials, API, MCP.</p></div><div><small>05 / CHECK</small><b>Verify claims</b><p>Exact quote plus entailment check.</p></div><div><small>06 / SERVE</small><b>PostgreSQL</b><p>Cache runs; show sources and status.</p></div></div><div class="callout"><b>Where a human is needed:</b> adjudicate ambiguous or conflicting documentation, check a representative sample against the original pages, and investigate gated apps that require accounts or partner contact.</div></section>
<section class="section" id="proof"><div class="section-title"><div><span class="eyebrow">PROOF</span><h2>Run it yourself</h2></div><p>This page is generated from stored research records, not written by hand. The local app and batch pipeline are documented in README.md.</p></div><div class="two-col"><div class="box"><h3>Research trigger</h3><p><code>cd backend && python -m app.cli run --all</code></p><p>Requires Tavily, Gemini and a configured database; export with <code>python -m app.cli export</code>.</p></div><div class="box"><h3>Product UI</h3><p>Run FastAPI on port 8000 and Next.js on port 3000 for the live chat, 100-app matrix, insights, verification and methodology views.</p></div></div></section>
<section class="section" id="verification"><div class="section-title"><div><span class="eyebrow">VERIFICATION</span><h2>Accuracy ledger</h2></div><p>Automatic evidence checking and manual accuracy auditing are separate. An accuracy improvement is reported only when first-pass outputs and human judgments exist.</p></div><div class="audit"><div class="box"><h3>Claim-level outcomes</h3><div class="audit-num"><div><strong>{supported}</strong><span>SUPPORTED</span></div><div><strong>{withheld}</strong><span>WITHHELD</span></div><div><strong>{verification['human_reviews']}</strong><span>HUMAN CHECKS</span></div></div><p>Every source URL must be in an extracted result. The quote must occur in that source. Gemini then judges whether it entails the claim. Only supported claims enter the dossier.</p>{accuracy_html}</div><div class="box"><h3>Actual hits and misses</h3>{misses}</div></div></section>
</main><script>const input=document.getElementById('app-search'),rows=[...document.querySelectorAll('#app-table tbody tr')],count=document.getElementById('row-count');input.addEventListener('input',()=>{{const q=input.value.toLowerCase();let visible=0;rows.forEach(row=>{{const show=row.textContent.toLowerCase().includes(q);row.hidden=!show;if(show)visible++}});count.textContent=visible+' applications'}});</script></body></html>'''
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(html_doc)
